example.expectedOutput:
{
"thoughtProcess": "'SIP 1.2 lakhs per year' → ANNUAL period mismatch with monthlySipCommitment → unmappedFields.
'rent 20k a month' → monthlyRent matches.",
"clauseSegments": [
{"text": "My mutual fund SIP is 1.2 lakhs per year", "type": "FACT"},
{"text": "and my rent is 20k a month", "type": "FACT"}
],
"mappedFields": [
{"key": "monthlyRent", "value": "20k", "fieldType": "CURRENCY", "rawSpan": "rent is 20k a month",
"period": "MONTHLY",
"entityMeta": {"entityGroupId": "HOUSEHOLD_1", "relationshipToUser": "HOUSEHOLD"}, "confidenceScore": "HIGH"}
],
"unmappedFields": [
{"key": "annualSipCommitment", "value": "1.2 lakhs", "fieldType": "CURRENCY", "rawSpan": "SIP is 1.2 lakhs per
year", "period": "ANNUAL",
"entityMeta": {"entityGroupId": "PERSON_1", "relationshipToUser": "SELF"}, "confidenceScore": "HIGH"}
],
"modifiers": []
}

{
"thoughtProcess": "'the kid' — two children exist (CHILD_1/5, CHILD_2/3), ambiguous → entityGroupId null.
'my parent' — single parent (PARENT_1/Sunita) → resolved.",
"clauseSegments": [
{"text": "the kid's school fees are 50k per month", "type": "FACT"},
{"text": "my parent needs 15k for medicines", "type": "FACT"}
],
"mappedFields": [],
"unmappedFields": [
{"key": "monthlySchoolFees", "value": "50k", "fieldType": "CURRENCY", "rawSpan": "the kid's school fees are 50k
per month", "period": "MONTHLY",
"entityMeta": {"entityGroupId": null, "relationshipToUser": "CHILD"},
"clarificationNote": "Which of your kids has the school fees — the 5-year-old or the 3-year-old?",
"confidenceScore": "LOW"},
{"key": "monthlyMedicalExpenses", "value": "15k", "fieldType": "CURRENCY", "rawSpan": "my parent needs 15k for
medicines", "period": "MONTHLY",
"entityMeta": {"entityGroupId": "PARENT_1", "relationshipToUser": "PARENT"}, "confidenceScore": "HIGH"}
],
"modifiers": []
}

flashExtractionPrompt.responseSchema:
{
  "type": "OBJECT",
  "required": [
    "thoughtProcess",
    "clauseSegments",
    "mappedFields",
    "unmappedFields",
    "modifiers"
  ],
  "properties": {
    "thoughtProcess": {
      "type": "STRING",
      "description": "Step-by-step reasoning: list raw numbers, categorize each clause, resolve entityGroupIds via knownEntitySummaries (or assign new sequential IDs), check duplicates, confirm canonical key uniqueness BEFORE writing mappedFields."
    },
    "clauseSegments": {
      "type": "ARRAY",
      "description": "Every logical segment of the user input. REQUIRED — use [] if none. Types: FACT, MODIFIER, RELATIONSHIP.",
      "items": {
        "type": "OBJECT",
        "required": [
          "text",
          "type"
        ],
        "properties": {
          "text": {
            "type": "STRING"
          },
          "type": {
            "type": "STRING"
          }
        }
      }
    },
    "mappedFields": {
      "type": "ARRAY",
      "description": "REQUIRED — use []. Every field that maps to the canonical schema. MUST include all fields identified in thoughtProcess. Do NOT leave mapped fields only in thoughtProcess. Keys MUST be person-agnostic (e.g., 'age', 'monthlyNetIncome') — NEVER entity-prefixed. Use entityMeta to identify the entity.",
      "items": {
        "type": "OBJECT",
        "required": [
          "key",
          "value",
          "entityMeta"
        ],
        "properties": {
          "key": {
            "type": "STRING",
            "description": "Person-agnostic canonical field key (e.g., 'age', 'monthlyNetIncome'). NEVER entity-prefixed (NEVER 'child_1_age', 'spouseIncome')."
          },
          "value": {
            "type": "STRING"
          },
          "entityMeta": {
            "type": "OBJECT",
            "description": "REQUIRED. Entity context — identifies WHICH person/entity this field belongs to.",
            "required": ["relationshipToUser"],
            "properties": {
              "entityGroupId": {
                "type": "STRING",
                "nullable": true,
                "description": "Entity group ID (e.g., 'PERSON_1', 'CHILD_1', 'HOUSEHOLD_1'). Null when entity is ambiguous."
              },
              "relationshipToUser": {
                "type": "STRING",
                "enum": ["SELF", "SPOUSE", "PARENT", "CHILD", "HOUSEHOLD", "SIBLING", "OTHER"],
                "description": "The entity's relationship to the primary user."
              }
            }
          },
          "clarificationNote": {
            "type": "STRING",
            "nullable": true,
            "description": "When there is ambiguity about the field or entity. A short, conversational question to ask the user. Never use system jargon."
          },
          "fieldType": {
            "type": "STRING"
          },
          "period": {
            "type": "STRING"
          },
          "qualifier": {
            "type": "STRING"
          },
          "rawSpan": {
            "type": "STRING"
          },
          "inferredValue": {
            "type": "STRING"
          },
          "confidenceScore": {
            "type": "STRING",
            "enum": ["HIGH", "MEDIUM", "LOW"]
          }
        }
      }
    },
    "unmappedFields": {
      "type": "ARRAY",
      "description": "REQUIRED — use []. Fields that do not match any canonical schema key. Keys MUST be person-agnostic (e.g., 'carLoanRemaining') — NEVER entity-prefixed. Use entityMeta to identify the entity.",
      "items": {
        "type": "OBJECT",
        "required": [
          "key",
          "value",
          "entityMeta"
        ],
        "properties": {
          "key": {
            "type": "STRING",
            "description": "Person-agnostic descriptive key (e.g., 'carLoanRemaining', 'investmentStartDate'). NEVER entity-prefixed (NEVER 'spouse_income', 'child_1_name')."
          },
          "value": {
            "type": "STRING"
          },
          "entityMeta": {
            "type": "OBJECT",
            "description": "REQUIRED. Entity context — identifies WHICH person/entity this field belongs to.",
            "required": ["relationshipToUser"],
            "properties": {
              "entityGroupId": {
                "type": "STRING",
                "nullable": true,
                "description": "Entity group ID (e.g., 'PERSON_1', 'CHILD_1', 'HOUSEHOLD_1'). Null when entity is ambiguous."
              },
              "relationshipToUser": {
                "type": "STRING",
                "enum": ["SELF", "SPOUSE", "PARENT", "CHILD", "HOUSEHOLD", "SIBLING", "OTHER"],
                "description": "The entity's relationship to the primary user."
              }
            }
          },
          "clarificationNote": {
            "type": "STRING",
            "nullable": true,
            "description": "When there is ambiguity about the field or entity. A short, conversational question to ask the user. Never use system jargon."
          },
          "fieldType": {
            "type": "STRING"
          },
          "period": {
            "type": "STRING"
          },
          "qualifier": {
            "type": "STRING"
          },
          "rawSpan": {
            "type": "STRING"
          },
          "inferredValue": {
            "type": "STRING"
          },
          "confidenceScore": {
            "type": "STRING",
            "enum": ["HIGH", "MEDIUM", "LOW"]
          }
        }
      }
    },
    "modifiers": {
      "type": "ARRAY",
      "description": "REQUIRED — use []. What-if scenarios or conditional changes.",
      "items": {
        "type": "OBJECT",
        "required": [
          "targetField",
          "operation"
        ],
        "properties": {
          "targetField": {
            "type": "STRING"
          },
          "operation": {
            "type": "STRING"
          },
          "value": {
            "type": "STRING"
          },
          "period": {
            "type": "STRING"
          },
          "compareGroup": {
            "type": "STRING"
          },
          "conditionContext": {
            "type": "STRING"
          },
          "rawSpan": {
            "type": "STRING"
          },
          "confidenceScore": {
            "type": "STRING",
            "enum": ["HIGH", "MEDIUM", "LOW"]
          }
        }
      }
    }
  }
}
